#include "touch.h"
#include <cstdio>
namespace {unsigned checks{},failures{};void verify(bool ok,const char* name){++checks;if(!ok){++failures;std::fprintf(stderr,"SELECTION_INTENT_FAIL %s\n",name);}}void event(reader::Touch& t,unsigned short type,unsigned short code,int value,spike::Ns at){input_event e{};e.type=type;e.code=code;e.value=value;(void)t.feed(e,false,at);}void down(reader::Touch& t,int x=1000,int y=900){t.testAxes({0,1619},{0,2159});event(t,EV_ABS,ABS_MT_TRACKING_ID,7,1);event(t,EV_ABS,ABS_MT_POSITION_X,x,1);event(t,EV_ABS,ABS_MT_POSITION_Y,y,1);event(t,EV_SYN,SYN_REPORT,0,1);}void move(reader::Touch& t,int x,int y,spike::Ns at){event(t,EV_ABS,ABS_MT_POSITION_X,x,at);event(t,EV_ABS,ABS_MT_POSITION_Y,y,at);event(t,EV_SYN,SYN_REPORT,0,at);}reader::Touch::Tap lift(reader::Touch& t,spike::Ns at){event(t,EV_ABS,ABS_MT_TRACKING_ID,-1,at);event(t,EV_SYN,SYN_REPORT,0,at);return t.takeTap();}}
int main(){using G=reader::Gesture;for(auto duration:{200000000ULL,600000000ULL,799000000ULL})for(int direction:{-1,1}){reader::Touch t;t.selectionMode(true,17);down(t,800);move(t,800+direction*80,905,50000001);(void)t.takeTap();move(t,800+direction*450,915,duration-10000000);(void)t.takeTap();auto a=lift(t,duration);verify(a.valid&&!a.drag&&a.gesture==(direction<0?G::SwipeNext:G::SwipePrevious),"pagination_keeps_800ms_window_in_selection_mode");}for(int dy:{-350,350}){reader::Touch t;t.selectionMode(true,17);down(t);move(t,1010,900+dy,100000001);(void)t.takeTap();auto a=lift(t,600000001);verify(!a.drag,"moving_vertical_finger_without_selection_intent_is_not_text_selection");}{reader::Touch t;t.selectionMode(true,17);down(t);t.expire(500000001);verify(t.takeTap().longPress,"intentional_long_press_selects");move(t,800,940,600000001);verify(!t.takeTap().cancelled,"intentional_long_press_drag_is_not_cancelled_by_its_own_motion");auto a=lift(t,900000001);verify(a.valid&&a.drag&&a.gesture==G::None,"intentional_long_press_drag_remains_text_selection");}{reader::Touch t;t.selectionMode(true,17);down(t);move(t,850,910,100000001);t.selectionMode(true,18);auto a=lift(t,300000001);verify(!a.valid,"stale_page_epoch_cancels_selection_and_navigation");}for(auto mode:{reader::DragMode::Ink,reader::DragMode::Scroll}){reader::Touch t;t.interactionMode(mode,17);down(t);t.expire(500000001);verify(!t.takeTap().valid,"ink_and_scroll_owners_do_not_start_text_long_press");move(t,500,910,600000001);auto a=lift(t,700000001);verify(a.valid&&a.drag&&a.mode==mode&&a.gesture==G::None,"ink_and_scroll_drags_never_turn_pages_behind_their_panel");}{reader::Touch t;down(t);t.expire(500000001);verify(t.takeTap().longPress,"ordinary_reading_long_press_is_retained");t.interactionMode(reader::DragMode::Text,0);move(t,800,940,600000001);auto a=lift(t,900000001);verify(a.valid&&a.drag&&a.mode==reader::DragMode::Text,"long_press_can_promote_to_deliberate_text_drag");}for(auto area:{spike::Rect{0,0,112,2060},spike::Rect{1508,0,1620,2060}}){reader::Touch t;t.interactionMode(reader::DragMode::Text,17);t.toolbar(area);int x=(area.x0+area.x1)/2;down(t,x,500);t.expire(500000001);verify(!t.takeTap().valid,"toolbar_contact_does_not_start_text_long_press");move(t,x+(area.x0==0?450:-450),510,600000001);auto a=lift(t,700000001);verify(!a.valid,"toolbar_start_cannot_navigate_or_select_document");}{reader::Touch t;t.interactionMode(reader::DragMode::Highlight,17);down(t,400,900);move(t,1000,940,500000001);auto a=lift(t,600000001);verify(a.valid&&a.drag&&a.mode==reader::DragMode::Highlight&&a.gesture==reader::Gesture::None,"deliberate_highlighter_dwell_drag_is_not_pagination");}std::printf("SELECTION_INTENT_CHECKS checks=%u failures=%u raw_input=NONE physical=NOT_RUN\n",checks,failures);return failures?1:0;}
